export interface Movable { position: Position }   // structural capability

export function moveTo(shape: Movable, to: Position): void {   // the servant
  shape.position = to;
}

// runtime member syntax needs a mixin class expression, not prototype patching
function MovableMixin<TBase extends new (...args: any[]) => object>(Base: TBase) {
  return class extends Base { moveTo(to: Position) { (this as Movable).position = to; } };
}
